proyecto.archivo:
:root {
    color-scheme: light;
    color: #20231c;
    background: #f3f5ef;
    font-family: var(--font-body);
    font-synthesis: none;
    --font-heading: 'New Tegomin', serif;
    --font-body: 'New Tegomin', serif;
}

body, input, textarea, select, button {
    font-family: var(--font-body);
}

* {
    box-sizing: border-box;
}

body {
    margin: 0;
}

button,
input,
textarea {
    font: inherit;
}

input[type="file"]::file-selector-button,
input[type="file"]::-webkit-file-upload-button {
    font-family: var(--font-body);
}

.admin-shell {
    width: min(100% - 2rem, 920px);
    margin: 0 auto;
    padding: 2rem 0 4rem;
}

.back-link {
    color: #4a6e18;
    text-decoration: none;
}

.admin-header {
    margin: 2rem 0;
}

.eyebrow {
    color: #4a6e18;
    font-size: 0.8rem;
    font-weight: 700;
    letter-spacing: 0.12em;
}

h1,
h2,
p {
    margin-top: 0;
}

h1 {
    margin-bottom: 0.25rem;
    font-size: clamp(2rem, 6vw, 3rem);
}

.admin-header > p:last-child {
    color: #64695f;
}

.panel,
.product-entry {
    padding: 1.25rem;
    border: 1px solid #dce1d4;
    border-radius: 14px;
    background: #fff;
    box-shadow: 0 8px 24px rgba(32, 35, 28, 0.05);
}

.panel h2,
.catalog-heading h2 {
    margin-bottom: 1rem;
}

.stack-form,
.product-form {
    display: grid;
    gap: 1rem;
}

.stack-form label,
.product-form label {
    display: grid;
    gap: 0.4rem;
    font-size: 0.9rem;
    font-weight: 650;
}

.password-field {
    display: flex;
    gap: 0.5rem;
}

.password-field input {
    flex: 1;
}

input,
textarea {
    width: 100%;
    min-width: 0;
    padding: 0.7rem 0.75rem;
    border: 1px solid #c9cfc1;
    border-radius: 8px;
    background: #fff;
    color: #20231c;
}

input:focus,
textarea:focus {
    outline: 2px solid #749445;
    outline-offset: 1px;
}

textarea {
    resize: vertical;
}

.primary-button,
.secondary-button {
    min-height: 42px;
    padding: 0.6rem 1rem;
    border: 0;
    border-radius: 8px;
    cursor: pointer;
    font-weight: 700;
}

.primary-button {
    background: #4a6e18;
    color: white;
}

.secondary-button {
    border: 1px solid #bdc5b2;
    background: white;
    color: #39442d;
}

button:disabled {
    cursor: wait;
    opacity: 0.65;
}

.status-message {
    margin-bottom: 1rem;
}

.status-message:empty {
    display: none;
}

.status-message[data-type="error"] {
    color: #a32121;
}

.status-message[data-type="success"] {
    color: #356412;
}

.catalog-heading {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
    margin: 2rem 0 1rem;
}

.product-list {
    display: grid;
    gap: 1rem;
}

.product-entry h3 {
    margin-bottom: 1rem;
}

.product-form {
    grid-template-columns: repeat(2, minmax(0, 1fr));
}

.wide-field {
    grid-column: 1 / -1;
}

.form-actions {
    display: flex;
    justify-content: space-between;
    gap: 0.75rem;
}

.delete-button {
    border: 1px solid #b43a35;
    background: white;
    color: #a32121;
}

.empty-list {
    padding: 1rem;
    color: #64695f;
}

[hidden] {
    display: none !important;
}

@media (max-width: 600px) {
    .product-form {
        grid-template-columns: minmax(0, 1fr);
    }

    .wide-field {
        grid-column: auto;
    }

    .form-actions {
        flex-direction: column;
    }
}

const statusMessage = document.querySelector("#status-message");
const loginSection = document.querySelector("#login-section");
const catalogSection = document.querySelector("#catalog-section");
const loginForm = document.querySelector("#login-form");
const loginPassword = loginForm.querySelector("#login-password");
const togglePasswordButton = loginForm.querySelector("#toggle-password");
const productList = document.querySelector("#product-list");
const addProductForm = document.querySelector("#add-product-form");
const config = window.supabaseConfig;
const imageBucket = "product-images";
const maxImageSize = 10 * 1024 * 1024;
const imageExtensions = {
    "image/avif": "avif",
    "image/gif": "gif",
    "image/jpeg": "jpg",
    "image/png": "png",
    "image/webp": "webp"
};
let supabaseClient = null;

togglePasswordButton.addEventListener("click", () => {
    const isPasswordVisible = loginPassword.type === "text";
    loginPassword.type = isPasswordVisible ? "password" : "text";
    togglePasswordButton.textContent = isPasswordVisible ? "Mostrar" : "Ocultar";
    togglePasswordButton.setAttribute("aria-pressed", String(!isPasswordVisible));
});

function showStatus(message, type = "") {
    statusMessage.textContent = message;
    statusMessage.dataset.type = type;
}

function getWhatsAppUrl(form) {
    const values = new FormData(form);
    const whatsappUrl = values.get("whatsappUrl").trim();
    if (new URL(whatsappUrl).protocol !== "https:") {
        throw new Error("El enlace de WhatsApp debe usar HTTPS.");
    }

    return whatsappUrl;
}

function validateProductImage(form) {
    const values = new FormData(form);
    const hasUploadedFile = form.querySelector("input[name='imageFile']").files.length > 0;
    if (!values.get("image").trim() && !hasUploadedFile) {
        throw new Error("Indica una imagen o selecciona una foto para subir.");
    }
}

function getProductValues(form, uploadedImage) {
    const values = new FormData(form);
    const whatsappUrl = getWhatsAppUrl(form);
    const image = uploadedImage || values.get("image").trim();
    if (!image) {
        throw new Error("Indica una imagen o selecciona una foto para subir.");
    }

    return {
        image,
        name: values.get("name").trim(),
        description: values.get("description").trim(),
        price: values.get("price").trim(),
        whatsapp_url: whatsappUrl,
        tag: values.get("tag").trim() || null
    };
}

function createField(labelText, name, value, options = {}) {
    const label = document.createElement("label");
    label.textContent = labelText;

    const input = options.multiline
        ? document.createElement("textarea")
        : document.createElement("input");
    input.name = name;
    input.value = value || "";
    input.required = options.required !== false;
    if (options.multiline) {
        input.rows = 3;
    } else {
        input.type = options.type || "text";
    }

    label.append(input);
    if (options.wide) {
        label.classList.add("wide-field");
    }
    return label;
}

async function uploadProductImage(form) {
    getWhatsAppUrl(form);
    validateProductImage(form);
    const file = form.querySelector("input[name='imageFile']").files[0];
    if (!file) {
        return null;
    }
    if (!Object.prototype.hasOwnProperty.call(imageExtensions, file.type)) {
        throw new Error("El archivo debe ser una imagen JPG, PNG, WebP, GIF o AVIF.");
    }
    if (file.size > maxImageSize) {
        throw new Error("La imagen no puede superar los 10 MB.");
    }

    const path = `products/${Date.now()}-${Math.random().toString(36).slice(2)}.${imageExtensions[file.type]}`;
    const { error } = await supabaseClient.storage
        .from(imageBucket)
        .upload(path, file, { cacheControl: "3600", contentType: file.type, upsert: false });
    if (error) {
        if (error.message === "Bucket not found") {
            throw new Error('No existe el almacenamiento "product-images". Ejecuta el supabase-setup.sql actualizado en SQL Editor de Supabase.');
        }
        throw error;
    }

    const { data } = supabaseClient.storage.from(imageBucket).getPublicUrl(path);
    return data.publicUrl;
}

function createProductForm(product) {
    const form = document.createElement("form");
    form.className = "product-entry product-form";
    form.dataset.productId = product.id;

    const heading = document.createElement("h3");
    heading.textContent = product.name;
    heading.className = "wide-field";
    const imageField = createField("Imagen actual (ruta del sitio o URL)", "image", product.image, { required: false });
    const imageUploadLabel = document.createElement("label");
    imageUploadLabel.textContent = "Subir foto nueva (opcional)";
    const imageUpload = document.createElement("input");
    imageUpload.type = "file";
    imageUpload.name = "imageFile";
    imageUpload.accept = Object.keys(imageExtensions).join(",");
    imageUploadLabel.append(imageUpload);
    form.append(
        heading,
        imageField,
        imageUploadLabel,
        createField("Nombre", "name", product.name),
        createField("DescripciÃ³n", "description", product.description, { multiline: true, wide: true }),
        createField("Precio", "price", product.price),
        createField("Enlace de WhatsApp", "whatsappUrl", product.whatsapp_url, { type: "url" }),
        createField("Etiqueta (opcional)", "tag", product.tag, { required: false })
    );

    const actions = document.createElement("div");
    actions.className = "wide-field form-actions";

    const saveButton = document.createElement("button");
    saveButton.className = "primary-button";
    saveButton.type = "submit";
    saveButton.textContent = "Guardar cambios";

    const deleteButton = document.createElement("button");
    deleteButton.className = "primary-button delete-button";
    deleteButton.type = "button";
    deleteButton.dataset.action = "delete";
    deleteButton.textContent = "Eliminar producto";

    actions.append(saveButton, deleteButton);
    form.append(actions);
    return form;
}

async function loadProducts() {
    if (!supabaseClient) {
        throw new Error("Supabase no estÃ¡ inicializado.");
    }

    showStatus("Cargando catÃ¡logoâ€¦");
    const { data, error } = await supabaseClient
        .from("products")
        .select("id, image, name, description, price, whatsapp_url, tag, sort_order")
        .order("sort_order", { ascending: true });

    if (error) {
        throw error;
    }

    productList.replaceChildren();
    if (data.length === 0) {
        const emptyMessage = document.createElement("p");
        emptyMessage.className = "empty-list";
        emptyMessage.textContent = "TodavÃ­a no hay productos. Agrega el primero abajo.";
        productList.append(emptyMessage);
    } else {
        data.forEach((product) => productList.append(createProductForm(product)));
    }
    showStatus("");
}

function setAuthenticated(isAuthenticated) {
    loginSection.hidden = isAuthenticated;
    catalogSection.hidden = !isAuthenticated;
}

if (!config || !config.url || !config.anonKey) {
    showStatus("Falta configurar la URL y la clave pÃºblica de Supabase en supabase-config.js.", "error");
    loginForm.querySelector("button[type='submit']").disabled = true;
} else if (!window.supabase || typeof window.supabase.createClient !== "function") {
    showStatus("No se pudo cargar Supabase. Revisa tu conexiÃ³n a internet e intÃ©ntalo de nuevo.", "error");
    loginForm.querySelector("button[type='submit']").disabled = true;
} else {
    supabaseClient = window.supabase.createClient(config.url, config.anonKey);

    async function openCatalog() {
        setAuthenticated(true);
        try {
            await loadProducts();
        } catch (error) {
            console.error(error);
            showStatus(`No se pudo cargar el catÃ¡logo. Verifica los permisos de administrador: ${error.message}`, "error");
        }
    }

    loginForm.addEventListener("submit", async (event) => {
        event.preventDefault();
        const values = new FormData(loginForm);
        const submitButton = loginForm.querySelector("button[type='submit']");
        submitButton.disabled = true;
        showStatus("Validando accesoâ€¦");

        try {
            const { error } = await supabaseClient.auth.signInWithPassword({
                email: values.get("email").trim(),
                password: values.get("password")
            });

            if (error) {
                showStatus(`No se pudo iniciar sesiÃ³n: ${error.message}`, "error");
                return;
            }
            await openCatalog();
        } catch (error) {
            showStatus(`No se pudo iniciar sesiÃ³n: ${error.message}`, "error");
        } finally {
            submitButton.disabled = false;
        }
    });

    document.querySelector("#logout-button").addEventListener("click", async () => {
        try {
            const { error } = await supabaseClient.auth.signOut();
            if (error) {
                showStatus(`No se pudo cerrar sesiÃ³n: ${error.message}`, "error");
                return;
            }
            setAuthenticated(false);
            showStatus("SesiÃ³n cerrada.", "success");
        } catch (error) {
            showStatus(`No se pudo cerrar sesiÃ³n: ${error.message}`, "error");
        }
    });

    productList.addEventListener("submit", async (event) => {
        if (!(event.target instanceof HTMLFormElement)) {
            return;
        }
        event.preventDefault();
        const form = event.target;
        const saveButton = form.querySelector("button[type='submit']");
        saveButton.disabled = true;
        try {
            const uploadedImage = await uploadProductImage(form);
            const { error } = await supabaseClient
                .from("products")
                .update(getProductValues(form, uploadedImage))
                .eq("id", form.dataset.productId);

            if (error) {
                throw error;
            }
            showStatus("Producto actualizado.", "success");
            await loadProducts();
        } catch (error) {
            showStatus(`No se pudieron guardar los cambios: ${error.message}`, "error");
        } finally {
            saveButton.disabled = false;
        }
    });

    productList.addEventListener("click", async (event) => {
        if (!(event.target instanceof Element)) {
            return;
        }
        const button = event.target.closest("button[data-action='delete']");
        if (!button) {
            return;
        }

        const form = button.closest("form");
        const productName = form.querySelector("input[name='name']").value;
        if (!window.confirm(`Â¿Eliminar por completo "${productName}"? Esta acciÃ³n no se puede deshacer.`)) {
            return;
        }

        button.disabled = true;
        try {
            const { error } = await supabaseClient
                .from("products")
                .delete()
                .eq("id", form.dataset.productId);
            if (error) {
                throw error;
            }
            showStatus("Producto eliminado.", "success");
            await loadProducts();
        } catch (error) {
            button.disabled = false;
            showStatus(`No se pudo eliminar el producto: ${error.message}`, "error");
        }
    });

    addProductForm.addEventListener("submit", async (event) => {
        event.preventDefault();
        const submitButton = addProductForm.querySelector("button[type='submit']");
        submitButton.disabled = true;

        try {
            const uploadedImage = await uploadProductImage(addProductForm);
            const { data, error: listError } = await supabaseClient
                .from("products")
                .select("sort_order")
                .order("sort_order", { ascending: false })
                .limit(1);
            if (listError) {
                throw listError;
            }

            const nextOrder = data.length ? data[0].sort_order + 1 : 0;
            const { error } = await supabaseClient
                .from("products")
                .insert({ ...getProductValues(addProductForm, uploadedImage), sort_order: nextOrder });
            if (error) {
                throw error;
            }

            addProductForm.reset();
            showStatus("Producto agregado.", "success");
            await loadProducts();
        } catch (error) {
            showStatus(`No se pudo agregar el producto: ${error.message}`, "error");
        } finally {
            submitButton.disabled = false;
        }
    });

    supabaseClient.auth.getSession()
        .then(({ data, error }) => {
            if (error) {
                showStatus(`No se pudo verificar la sesiÃ³n: ${error.message}`, "error");
                return;
            }
            if (data.session) {
                openCatalog();
            }
        })
        .catch((error) => {
            showStatus(`No se pudo verificar la sesiÃ³n: ${error.message}`, "error");
        });
}

const productsGrid = document.querySelector("#products-grid");
const menuToggle = document.querySelector(".menu-toggle");
const navLinks = document.querySelector("#nav-links");

if (menuToggle && navLinks) {
    const closeMenu = () => {
        menuToggle.setAttribute("aria-expanded", "false");
        menuToggle.setAttribute("aria-label", "Abrir menÃº");
        navLinks.classList.remove("is-open");
    };

    menuToggle.addEventListener("click", () => {
        const isExpanded = menuToggle.getAttribute("aria-expanded") === "true";
        menuToggle.setAttribute("aria-expanded", String(!isExpanded));
        menuToggle.setAttribute("aria-label", isExpanded ? "Abrir menÃº" : "Cerrar menÃº");
        navLinks.classList.toggle("is-open", !isExpanded);
    });

    navLinks.addEventListener("click", (event) => {
        if (event.target instanceof Element && event.target.closest("a")) {
            closeMenu();
        }
    });

    document.addEventListener("keydown", (event) => {
        if (event.key === "Escape") {
            closeMenu();
            menuToggle.focus();
        }
    });
}

if (!productsGrid) {
    throw new Error('No se encontrÃ³ el contenedor "#products-grid".');
}

function createProductCard(product) {
    const orderUrl = new URL(product.whatsappUrl, window.location.href);
    if (orderUrl.protocol !== "https:") {
        throw new Error(`El enlace para pedir "${product.name}" debe usar HTTPS.`);
    }

    const card = document.createElement("div");
    card.className = "product-card";

    const imageContainer = document.createElement("div");
    imageContainer.className = "product-image";

    const image = document.createElement("img");
    image.src = product.image;
    image.alt = product.name;
    image.loading = "lazy";
    imageContainer.append(image);

    if (product.tag) {
        const tag = document.createElement("span");
        tag.className = "tag";
        tag.textContent = product.tag;
        imageContainer.append(tag);
    }

    const info = document.createElement("div");
    info.className = "product-info";

    const name = document.createElement("h3");
    name.textContent = product.name;

    const price = document.createElement("p");
    price.className = "price";
    price.textContent = product.price;

    const description = document.createElement("p");
    description.className = "description";
    description.textContent = product.description;

    const orderButton = document.createElement("a");
    orderButton.href = orderUrl.href;
    orderButton.className = "btn-ws";
    orderButton.target = "_blank";
    orderButton.rel = "noopener noreferrer";

    const whatsappIcon = document.createElement("i");
    whatsappIcon.className = "fa-brands fa-whatsapp";
    orderButton.append(whatsappIcon, document.createTextNode(" Pedir por WhatsApp"));

    info.append(name, price, description, orderButton);
    card.append(imageContainer, info);

    return card;
}

function renderProducts(products) {
    productsGrid.replaceChildren();

    if (products.length === 0) {
        const emptyMessage = document.createElement("p");
        emptyMessage.className = "catalog-empty";
        emptyMessage.textContent = "Estamos preparando nuevos productos.";
        productsGrid.append(emptyMessage);
        return;
    }

    products.forEach((product) => {
        const requiredFields = ["image", "name", "description", "price", "whatsappUrl"];
        const missingField = requiredFields.find((field) => (
            typeof product[field] !== "string" || product[field].trim() === ""
        ));

        if (missingField) {
            throw new Error(`Falta el campo "${missingField}" en un producto del catÃ¡logo.`);
        }

        productsGrid.append(createProductCard(product));
    });
}

function showCatalogError(message) {
    const error = document.createElement("p");
    error.className = "catalog-error";
    error.setAttribute("role", "alert");
    error.textContent = message;
    productsGrid.replaceChildren(error);
}

async function loadProducts() {
    const config = window.supabaseConfig;
    const hasSupabaseConfig = config && config.url && config.anonKey;

    if (!hasSupabaseConfig) {
        const products = window.servicesData && window.servicesData.products;
        if (!Array.isArray(products)) {
            throw new Error("No se encontrÃ³ una lista vÃ¡lida de productos en services-data.js.");
        }
        renderProducts(products);
        return;
    }

    if (!window.supabase || typeof window.supabase.createClient !== "function") {
        throw new Error("No se pudo cargar Supabase. Revisa tu conexiÃ³n a internet e intÃ©ntalo de nuevo.");
    }

    const client = window.supabase.createClient(config.url, config.anonKey);
    const { data, error } = await client
        .from("products")
        .select("image, name, description, price, whatsapp_url, tag")
        .order("sort_order", { ascending: true });

    if (error) {
        throw new Error(`No se pudo cargar el catÃ¡logo: ${error.message}`);
    }

    renderProducts(data.map((product) => ({
        ...product,
        whatsappUrl: product.whatsapp_url
    })));
}

loadProducts().catch((error) => {
    console.error(error);
    showCatalogError("No pudimos cargar el catÃ¡logo en este momento. Intenta de nuevo mÃ¡s tarde.");
});

