/* ==========================================
   RESET & VARIABLES
   ========================================== */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

@font-face {
    font-family: 'Numbskull';
    src: url('Numbskull/Numbskull.otf') format('opentype');
    font-weight: normal;
    font-style: normal;
    font-display: swap;
}

:root {
    --bg-main: #0d0d11;
    --bg-card: #16161e;
    --accent: #ff4a8d;
    --accent-hover: #e03875;
    --whatsapp-color: #25d366;
    --whatsapp-hover: #1eae53;
    --text-primary: #ffffff;
    --text-secondary: #a0a0b2;
    --border-color: #262635;
    --font-heading: 'New Tegomin', serif;
    --font-body: 'New Tegomin', serif;
}

html {
    scroll-behavior: smooth;
}

body {
    position: relative;
    isolation: isolate;
    background-color: white;
    color: var(--text-primary);
    font-family: var(--font-body);
    line-height: 1.6;
    overflow-x: clip;
}

body::before {
    content: '';
    position: absolute;
    inset: 0;
    z-index: -1;
    background: url('real.jpeg') center top / 100% auto repeat-y;
    opacity: 0.5;
    pointer-events: none;
}

a {
    text-decoration: none;
    color: inherit;
}

/* ==========================================
   NAVBAR
   ========================================== */
/* --- BARRA DE NAVEGACIÃ“N GENERAL (DiseÃ±o de 3 columnas para centrar el logo) --- */
.navbar {
    display: grid;
    grid-template-columns: 1fr auto 1fr; /* Columna izq, centro automÃ¡tico para el logo, columna der */
    align-items: center;
    width: 100%;
    padding: 10px 30px;
    background-color: rgba(223, 247, 229, 0.9);
    backdrop-filter: blur(10px);
    position: sticky;
    top: 0;
    z-index: 1000;
    border-bottom: 1px solid var(--border-color);
}

/* --- MENÃš HAMBURGUESA (Ubicado en la columna 1: Izquierda) --- */
.menu-toggle {
    grid-column: 1;
    grid-row: 1;
    justify-self: start;
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: 5px;
    width: 40px;
    height: 40px;
    padding: 9px;
    border: 1px solid rgba(74, 110, 24, 0.6);
    border-radius: 10px;
    background: transparent;
    cursor: pointer;
}

.menu-toggle span {
    width: 100%;
    height: 2px;
    border-radius: 2px;
    background: rgba(74, 110, 24, 1);
}

/* --- LOGO (Ubicado en la columna 2: Centro) --- */
.logo {
    grid-column: 2;
    grid-row: 1;
    justify-self: center;
}

.logo a {
    font-family: var(--font-heading);
    font-size: 3rem;
    font-weight: 700;
    letter-spacing: 1px;
    display: flex;
    align-items: center;
    gap: 20px; /* Reducido para evitar desbordamientos, ajÃºstalo si lo necesitas */
    text-decoration: none;
    color: inherit;
}

.logo img {
    height: 2em;
    width: auto;
    object-fit: contain;
}

.logo span {
    color: var(--accent);
    margin-left: 5px;
    font-weight: 100;
    font-size: 3rem;
    line-height: 1.5;
    display: inline-block;
    transform: translateY(2px);
}

/* --- BOTÃ“N DE INSTAGRAM (Ubicado en la columna 3: Derecha) --- */
.ig-link {
    position: relative;
    grid-column: 3;
    grid-row: 1;
    justify-self: end; /* Lo manda por completo a la derecha */
    color: white;
    background-color: rgba(74, 110, 24, 0.3);
    padding: 0.5rem 1rem;
    border-radius: 20px;
    border: 1px solid rgba(74, 110, 24, 1);
    display: inline-flex;
    align-items: center;
    gap: 0.45rem;
    line-height: 1;
    white-space: nowrap;
    text-decoration: none;
    overflow: hidden;
    isolation: isolate;
    transition: background-color 0.3s ease, color 0.3s ease;
}

.ig-link::before {
    content: '';
    position: absolute;
    top: -60%;
    left: 100%;
    z-index: -1;
    width: 35%;
    height: 220%;
    background: linear-gradient(
        90deg,
        transparent,
        rgba(255, 255, 255, 0.18) 35%,
        rgba(255, 255, 255, 0.85) 50%,
        rgba(255, 255, 255, 0.18) 65%,
        transparent
    );
    filter: blur(1px);
    transform: skewX(-25deg);
    animation: secondary-shine 3s ease-in-out infinite;
    pointer-events: none;
}

.ig-link:hover {
    background-color: rgba(74, 110, 24, 0.7);
    color: #fff;
}

/* --- ENLACES DE NAVEGACIÃ“N / MENÃš DESPLEGABLE --- */
.nav-links {
    position: absolute;
    top: 100%;
    left: 0;
    display: none; /* Oculto por defecto, se muestra con la clase .is-open mediante JS */
    flex-direction: column;
    align-items: stretch;
    width: 100%;
    padding: 0.5rem 1rem;
    background-color: rgba(223, 247, 229, 0.98);
    border-bottom: 1px solid var(--border-color);
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.05);
    z-index: 999;
}

.nav-links.is-open {
    display: flex;
}

.nav-links a {
    color: var(--text-secondary);
    transition: color 0.3s ease;
    font-weight: 500;
    display: inline-flex;
    align-items: center;
    min-height: 44px;
    justify-content: center;
}

.nav-links a:hover {
    color: var(--text-primary);
}

/* ==========================================
   HERO SECTION
   ========================================== */
.hero {
    display: flex;
    justify-content: center;
    align-items: center;
    text-align: center;
    padding: 4rem 1rem 0.5rem;
}

.hero-content {
    max-width: 700px;
}

.badge {
    background-color: #222530; /* El tono oscuro que se ve en tu imagen */
    color: rgba(74, 110, 24, 1);
    font-size: 1.8rem; /* Al aumentar este valor, la altura del badge crecerÃ¡ sola */

    /* El primer nÃºmero (ej. 1rem) controla el espacio superior e inferior (altura) */
    /* El segundo nÃºmero (ej. 2.5rem) controla el espacio lateral (ancho) */
    padding: 1rem 3rem; 

    border-radius: 50px; /* Mantiene los bordes completamente redondeados */
    text-transform: capitalize;
    letter-spacing: 2px;
    font-weight: 600;

    display: inline-block; /* Obligatorio para que la caja respete los paddings y crezca */
    line-height: 1.2; /* Asegura una proporciÃ³n vertical correcta con el texto */
}

.hero-content > span.badge,
.hero-content a.badge[href] {
    border: 3px solid transparent;
    background:
        linear-gradient(#222530, #222530) padding-box,
        conic-gradient(from var(--a), #4a6e18, #dff7e5, #4a6e18) border-box;
    animation: spin 4s linear infinite;
}

.hero h1 {
    font-family: 'Numbskull', sans-serif;
    color: rgba(0, 0, 0, 0.753);
    font-size: 3.5rem;
    margin: 1.5rem 0 1rem;
    line-height: 1.1;
    font-weight: 600;
}

.hero h1 span {
    color: rgba(74, 110, 24, 1);
}

.hero p {
    color: rgba(0, 0, 0, 1);
    font-size: 1.2rem;
    margin-bottom: 2rem;
    line-height: 1;
    font-weight: bolder;
}

/* 1. Definimos la propiedad personalizada para que el navegador sepa animar el Ã¡ngulo */
@property --a {
    syntax: "";
    initial-value: 0deg;
    inherits: false;
}

/* 2. Definimos la animaciÃ³n de giro continuo */
@keyframes spin {
    to {
        --a: 360deg;
    }
}

/* 3. Estilos actualizados para tu botÃ³n principal con el borde animado */
.btn-primary {
    display: inline-block;
    position: relative;
    color: rgba(74, 110, 24, 1);
    padding: 0.9rem 2rem;
    border-radius: 30px;
    font-weight: 600;
    text-decoration: none;
    z-index: 1;

    /* Fondo interior negro y degradado cÃ³nico giratorio en el borde */
    background: linear-gradient(black, black), 
                conic-gradient(from var(--a), #4a6e18, #dff7e5, #4a6e18);

    background-clip: padding-box, border-box;
    -webkit-background-clip: padding-box, border-box;

    background-origin: border-box;

    /* Grosor del borde transparente para dejar ver el degradado giratorio */
    border: 5px solid transparent; 

    /* Aplicamos la animaciÃ³n */
    animation: spin 4s linear infinite;

    transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.btn-primary:hover {
    transform: translateY(-3px);
    box-shadow: 0 4px 15px rgba(74, 110, 24, 0.3); 
}

@media (prefers-reduced-motion: reduce) {
    .hero-content > span.badge,
    .hero-content a.badge[href],
    .btn-primary,
    .product-card,
    .btn-secondary::before,
    .ig-link::before {
        animation: none;
    }
}


/* ==========================================
   PRODUCTOS
   ========================================== */
.products-section {
    padding: 0.5rem 8% 5rem;
}

.section-title {
    text-align: center;
    margin-bottom: 3.5rem;
}

.section-title h2 {
    font-family: var(--font-heading);
    font-size: 2.5rem;
    color: rgba(0, 0, 0, 0.87);
}

.section-title p {
    color: rgba(0, 0, 0, 1);
    font-size: 1.2rem;
    margin-bottom: 2rem;
    line-height: 1;
    font-weight: bolder;
}

.products-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 2rem;
    justify-items: center;
    max-width: 1100px;
    margin: 0 auto;
    width: 100%
}

.products-grid > * {
    width: 100%;
    min-width: 0; 
}

.catalog-error {
    grid-column: 1 / -1;
    color: #a32121;
    text-align: center;
}

.catalog-empty {
    grid-column: 1 / -1;
    color: var(--text-secondary);
    text-align: center;
}

.product-card {
    width: 32rem;
    height: auto;
    border-radius: 16px;
    overflow: hidden;
    border: 4px solid transparent;
    background:
        linear-gradient(var(--bg-card), var(--bg-card)) padding-box,
        conic-gradient(from var(--a), #4a6e18, #dff7e5, #4a6e18) border-box;
    animation: spin 4s linear infinite;
    transition: transform 0.3s ease;
    display: flex;
    flex-direction: column;
}

.product-card:hover {
    transform: translateY(-8px);
}

.product-image {
    position: relative;
    width: 100%;
    height: auto;
    flex: 0 0 75%;
    overflow: hidden;
}

.product-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.5s ease;
}

.product-card:hover .product-image img {
    transform: scale(1.05);
}

.tag {
    position: absolute;
    top: 15px;
    right: 15px;
    background-color: rgba(74, 110, 24, 1);
    color: #fff;
    font-size: 0.75rem;
    padding: 0.3rem 0.8rem;
    border-radius: 12px;
    font-weight: 600;
}

.product-info {
    min-height: 0;
    padding: 0.75rem;
    display: flex;
    flex-direction: column;
    flex: 0 0 25%;
    overflow: visible;
    flex-grow: 1;
    height: auto;
}

.product-info h3 {
    font-size: 1rem;
    line-height: 1.25;
    margin-bottom: 0.25rem;
}

.product-info .price {
    font-size: 1.1rem;
    line-height: 1.2;
    font-weight: 700;
    color: rgba(74, 110, 24, 1);
    margin-bottom: 0.25rem;
}

.product-info .description {
    color: var(--text-secondary);
    font-size: 0.8rem;
    line-height: 1.35;
    margin-bottom: 0.5rem;
    flex-grow: 1;
}

.btn-ws {
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 8px;
    background-color: var(--whatsapp-color);
    color: #fff;
    padding: 0.55rem;
    font-size: 0.9rem;
    line-height: 1.2;
    border-radius: 10px;
    font-weight: 600;
    transition: background-color 0.3s ease;
}

.btn-ws:hover {
    background-color: var(--whatsapp-hover);
}

/* ==========================================
   ABOUT SECTION
   ========================================== */
.about-section {
    background-color: rgba(22, 22, 30, 0.76);
    padding: 5rem 8%;
    border-top: 1px solid var(--border-color);
    border-bottom: 1px solid var(--border-color);
}

.about-container {
    max-width: 700px;
    margin: 0 auto;
    text-align: center;
}

.about-container h2 {
    font-family: var(--font-heading);
    font-size: 2rem;
    margin-bottom: 1rem;
}

.about-container h2 span {
    font-family: 'Numbskull', sans-serif;
}

.about-container p {
    color: var(--text-secondary);
    margin-bottom: 2rem;
    line-height:1.5;
    font-weight: bolder;
}

.btn-secondary {
    display: inline-flex;
    position: relative;
    align-items: center;
    gap: 8px;
    border: 1px solid var(--border-color);
    padding: 0.8rem 1.8rem;
    border-radius: 20px;
    overflow: hidden;
    isolation: isolate;
    transition: all 0.3s ease;
}

.btn-secondary::before {
    content: '';
    position: absolute;
    top: -60%;
    left: 100%;
    z-index: -1;
    width: 35%;
    height: 220%;
    background: linear-gradient(
        90deg,
        transparent,
        rgba(255, 255, 255, 0.18) 35%,
        rgba(255, 255, 255, 0.85) 50%,
        rgba(255, 255, 255, 0.18) 65%,
        transparent
    );
    filter: blur(1px);
    transform: skewX(-25deg);
    animation: secondary-shine 3s ease-in-out infinite;
    pointer-events: none;
}

@keyframes secondary-shine {
    to {
        transform: translateX(-400%) skewX(-25deg);
    }
}

.btn-secondary:hover {
    background-color: #9c9999;
    color: #000;
}

/* ==========================================
   FOOTER
   ========================================== */
footer {
    width: 100%;
    background-color: var(--bg-main);
    text-align: center;
    padding: 1.5rem;
    color: var(--text-secondary);
    font-size: 0.85rem;
    font-weight: 600;
}

/* ==========================================
   WHATSAPP FLOAT
   ========================================== */
.whatsapp-float {
    position: fixed;
    bottom: 80px;
    right: 30px;
    width: 60px;
    height: 60px;
    background-color: var(--whatsapp-color);
    color: #fff;
    border-radius: 50%;
    display: flex;
    justify-content: center;
    align-items: center;
    font-size: 30px;
    box-shadow: 0 4px 15px rgba(37, 211, 102, 0.4);
    z-index: 2000;
    text-decoration: none;
    transition: var(--transition);
    animation: pulse 2s infinite;
}

.whatsapp-float:hover {
    transform: scale(1.1);
    background-color: var(--whatsapp-hover);
}

@keyframes pulse {
    0% { box-shadow: 0 0 0 0 rgba(37, 211, 102, 0.7); }
    70% { box-shadow: 0 0 0 15px rgba(37, 211, 102, 0); }
    100% { box-shadow: 0 0 0 0 rgba(37, 211, 102, 0); }
}

/* ==========================================
   RESPONSIVE
   ========================================== */
@media (max-width: 768px) {
    .navbar {
        display: grid;
        grid-template-columns: 1fr auto 1fr;
        min-height: 64px;
        padding: 0.5rem 1rem;
    }

    .menu-toggle {
        grid-column: 1;
        grid-row: 1;
        display: flex;
        flex-direction: column;
        justify-content: center;
        gap: 5px;
        width: 40px;
        height: 40px;
        padding: 9px;
        border: 1px solid rgba(74, 110, 24, 0.6);
        border-radius: 10px;
        background: transparent;
        cursor: pointer;
    }

    .menu-toggle span {
        width: 100%;
        height: 2px;
        border-radius: 2px;
        background: rgba(74, 110, 24, 1);
    }

    .logo {
        grid-column: 2;
        grid-row: 1;
    }

    .logo img {
        height: 3.5rem;
    }

    .nav-links {
        position: absolute;
        top: 100%;
        left: 0;
        display: none;
        flex-direction: column;
        align-items: stretch;
        gap: 0;
        width: 100%;
        padding: 0.5rem 1rem;
        background-color: rgba(223, 247, 229, 0.98);
        border-bottom: 1px solid var(--border-color);
    }

    .nav-links.is-open {
        display: flex;
    }

    .nav-links a {
        min-height: 44px;
        justify-content: center;
    }

    .ig-link {
        grid-column: 3;
        grid-row: 1;
        justify-self: end;
        padding: 0.45rem 0.6rem;
        font-size: 0.82rem;
    }

    .ig-link i {
        font-size: 1rem;
	padding: 0.3rem 0rem;
    }

    .hero {
        padding: 2rem 1.25rem 0.25rem;
    }

    .hero-content {
        max-width: 34rem;
    }

    .badge {
        /* Mantenemos tus valores base intactos para que el badge mida exactamente igual */
        font-size: 2rem; 
        padding: 0.5rem 1.5rem;
        letter-spacing: 1.5px;
        line-height: 1;
        width: auto;

        /* MAGIA AQUÃ: Esto agranda visualmente el badge (texto incluido) un 20% o 30% 
           sin cambiar el tamaÃ±o real de su caja ni alterar el diseÃ±o de alrededor */
        transform: scale(1.3); /* Puedes probar con 1.15 o 1.25 segÃºn lo grande que lo quieras */
        transform-origin: center; /* Asegura que crezca desde el centro */
        display: inline-block;
        margin: 10px 0; /* Un pequeÃ±o margen por si el efecto visual roba un poco de espacio con los elementos vecinos */
    }

    .hero h1 {
        font-size: clamp(2.1rem, 9vw, 2.8rem);
    }

    .hero p {
        font-size: 1.05rem;
    }

    .products-section {
        padding: 0.25rem 5% 3.5rem;
    }

    .about-section {
        padding: 3.5rem 5%;
    }

    .section-title {
        margin-bottom: 2rem;
    }

    .section-title h2 {
        font-size: 2rem;
        position: relative;
        top: -0.4rem;
        margin-bottom: 0.35rem;
    }
    .section-title p {
        font-size: 1.05rem;
    }

    .products-grid {
        grid-template-columns: minmax(0, 1fr);
        grid-auto-rows: auto;
        gap: 1.25rem;
    }

    .product-card {
        width: 100%;
        max-width: 32rem;
    }

    .product-image {
        flex: 0 0 auto;
    }

    .product-image img {
        display: block;
        height: auto;
    }

    .product-info {
        flex: 0 0 auto;
    }

    .whatsapp-float {
        width: 54px;
        height: 54px;
        right: max(16px, env(safe-area-inset-right));
        bottom: max(80px, env(safe-area-inset-bottom));
        font-size: 26px;
    }

    footer {
        padding: 1.5rem 5%;
    }
}

@media (max-width: 420px) {
    .hero {
        min-height: 46svh;
        padding-inline: 1rem;
    }

    .badge {
        font-size: 0.72rem;
        letter-spacing: 1.5px;
    }

    .products-section,
    .about-section {
        padding-inline: 1rem;
    }

    .product-info {
        padding: 1.15rem;
    }

    .about-container h2 {
        font-size: 1.75rem;
    }
}

